function setLanguage(language) {

    // Remember the user's language choice
    localStorage.setItem("language", language);

    // Find every element that has data-i18n
    document.querySelectorAll("[data-i18n]").forEach(element => {

        // Get the translation key
        const key = element.dataset.i18n;

        // Put the translated text into the element
        element.textContent = translations[language][key];

    });

}


// Get the user's saved language.
// If they haven't chosen one yet, use English.
const savedLanguage = localStorage.getItem("language") || "en";


// Apply the language when the page loads
setLanguage(savedLanguage);
